/* Unified entry points; original stores and detailed routes remain intact. */
(()=>{
 const S=window.REISeminar;
 function setup(){const hash=location.hash,current=/^#(?:recap|journey|seminars|workshop)/.test(hash)?'recap':/^#(?:workbook|notebook|guided|learn\/\d|practice)/.test(hash)?'workbook':/^#(?:tools|create|research|resource|chapters|examples|toolkit)/.test(hash)?'tools':'learn';
 const markup=S.sections.map(([id,label])=>`<a href="#${id}" ${id===current&&hash!=='#home'?'aria-current="page"':''}>${label}</a>`).join('');
 document.querySelector('#navigation').innerHTML=markup;const header=document.querySelector('.header-notebook');header.href='#workbook';header.innerHTML='My Workbook <span id="note-count" hidden>0</span>';
 if(hash==='#learn'&&!document.querySelector('.seminar-detailed')){const list=document.querySelector('.library-lessons');if(list&&typeof course!=='undefined')list.insertAdjacentHTML('afterend','<details class="seminar-detailed"><summary>Optional detailed guides and earlier lesson writing</summary><p>These longer guides support the seven short lessons. Existing drafts stay in My Workbook.</p>'+course.map((c,i)=>'<p><a href="#lesson/'+i+'">'+c.title+'</a></p>').join('')+'</details>');}document.querySelectorAll('.library-nav,.path-tabs').forEach(n=>{n.innerHTML=markup;n.setAttribute('aria-label','REI sections')});document.querySelectorAll('.seminar-nav a').forEach(a=>{if(a.hash==='#'+current)a.setAttribute('aria-current','page')});
 const dialog=document.querySelector('#space-navigator');if(dialog){dialog.querySelector('.path-menu-primary').innerHTML=S.sections.map(([id,label])=>`<section><h3>${label}</h3><a href="#${id}"><strong>${{recap:'Refresh the seminar',learn:'Seven short lessons',workbook:'Your writing and saved drafts',tools:'Search, plan and review'}[id]}</strong></a></section>`).join('');dialog.querySelectorAll('.path-menu-tools').forEach(x=>x.hidden=true);dialog.querySelector('.space-grid').innerHTML='';}
 if(hash==='#home'||hash==='#explore'||!hash){const cta=document.querySelector('.dream-cta');if(cta){const href=S.resume();cta.href=href;cta.textContent=href==='#learn'?'Start here':'Continue where you left off';}const intro=document.querySelector('.dream-intro');if(intro&&!intro.querySelector('.home-backup'))intro.insertAdjacentHTML('beforeend','<p class="home-backup"><a href="#recap">Read the seminar recap</a> · <a href="#backup">Download my workbook</a><br>Clearing browser data can remove your work. Keep a downloaded copy.</p>');}else if(hash!=='#welcome'&&hash!=='#backup'){try{localStorage.setItem('rei-last-study-route',hash)}catch{}}
 }
 addEventListener('rrh:route',setup);setup();
})();
